std::map<std::string, int> position_by_symbol(const std::vector<std::string>& syms, const std::vector<int>& qty) {
    std::map<std::string, int> pos;
    for (std::size_t i = 0; i < syms.size(); ++i) {
        pos[syms[i]] += qty[i];
    }
    return pos;
}

