#include <map>
#include <string>
#include <unordered_map>

double exposure(const std::unordered_map<std::string, double>& px, const std::map<std::string, int>& pos) {
    double total = 0;
    for (const auto& [sym, qty] : pos) {
        auto it = px.find(sym);
        if (it != px.end()) {
            total += qty * it->second;
        }
    }
    return total;
}

