#include <iostream>
#include <map>
#include <string>

int main() {
    std::map<std::string, int> fills;
    std::map<std::string, int> shares;
    std::string venue;
    int qty;
    while (std::cin >> venue >> qty) {
        ++fills[venue];
        shares[venue] += qty;
    }
    for (const auto& [v, n] : fills) {
        std::cout << v << ' ' << n << ' ' << shares[v] << '\n';
    }
    return 0;
}

screens.prose:
An order book keeps its price levels sorted, so a `std::map` keyed by price seems natural. A tick here is 0.1p.

```cpp
std::map<double, int> bids;
double best = 100.1;
bids[best] += 500;
bids[best + 0.1] += 300;  // one tick up
bids[100.2] += 200;       // an order at 100.2
std::cout << bids.size() << '\n';
```

